import{_ as e,c as t,o as s,af as p}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"關於子夏傳真偽","description":"子夏易傳 - 關於子夏傳真偽","frontmatter":{"title":"關於子夏傳真偽","description":"子夏易傳 - 關於子夏傳真偽"},"headers":[],"relativePath":"classics/zixia/001.md","filePath":"classics/zixia/001.md"}'),i={name:"classics/zixia/001.md"};function r(c,a,_,o,n,l){return s(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="關於子夏傳真偽" tabindex="-1">關於子夏傳真偽 <a class="header-anchor" href="#關於子夏傳真偽" aria-label="Permalink to “關於子夏傳真偽”">​</a></h1><p>注意</p><p>《子夏易傳》實為偽作，現今的《子夏易傳》不僅非子夏所撰，也並非完全為張弧所撰，而是出自眾家之手。但其內容卻具有一定的參考價值。它孕含了較多漢唐時期的《易》學思想，對於研究、探討《周易》古義有著不可替代的作用。</p><p>《子夏易傳》，一部被現代易學界認定為偽書的易學古籍，書稱作者卜子夏。《子夏易傳》一為二卷，一為十一卷。舊本題卜子夏（前 507 一？）所撰。</p><p>序：子夏姓卜名商，春秋末晉國溫（今河南溫縣）人，孔子的學生，為莒父宰。孔子死後，到魏國講學，主張國君要學習《春秋》，吸取歷史教訓，宣揚“死生有命，富貴在天”等觀點，李克、吳起都是其弟子，魏文侯也尊以為師，相傳《詩》、《春秋》等儒家經典就是由他傳授下來的。學術界歷來主張，此書為後人偽撰，而託附於子夏名下，《四庫全書總目》認為“其偽中生偽，至一至再而未已者，亦莫若是書”。</p><p>《隋書·經籍志》所著錄的二卷本，其實是魏晉間大興《易》學之風時為當時人所偽撰而流佈於世。據《唐會要》載：“開元七年詔”，當時因《子夏易傳》無傳習者，遂令儒官詳定，劉知已認為，此書不見於《漢書·藝文志》，至梁阮孝緒《七錄》始有著錄，作六卷，或雲韓嬰作，或雲丁寬作，而至為可疑。司馬貞認為，劉向《七略》有《子夏易傳》，但其書久佚，晉荀勖《中經簿》有《子夏易傳》四卷，或雲丁寬，是其已懷疑非子夏所撰。因此，唐玄宗採納了劉、司馬氏的建議，而停止向學校頒行。代宗以年，此本亡佚。</p><p>清馬國翰《玉函山房輯佚書》中有輯佚本。今所傳十一卷本，始為晁說之《傳易堂記》所著錄，其稱“今稱《子夏傳》者，乃唐張弧之《易》。據此，則今本應是張弧偽撰。弧為唐末人，曾官大理寺評事。其書以王弼《周易注》為底本而說以義理，所說義理，大致上以儒家“王道”的社會政治思想與《周易》經文相附會。</p><p>迨朱彝尊作《經義考》，證以陸德明《經典釋文》、李鼎祚《周易集解》及王應麟《困學紀聞》所引諸條目，則於今本全無，知張弧偽撰之書又遭後人增削偽纂，並又多衍出一卷，為十一卷。因此，今本《於夏易傳》不但不是子夏所撰，亦並非完全為張弧所撰，雲其出自眾家之手，可謂不誣。</p><p>二本雖為偽造，但其內容卻有—定的參考價值，孕含了較多漢唐時期的《易》學思想，《四庫全書總目》雲“案說《易》之家，最古者莫若是書”，故其對研究、探討《周易》古義，二本參稽，仍為它書所不可替代。二卷本除為馬國翰所輯外，《漢學堂叢書·經解·逸書考》中亦有考輯。今本則有《四庫全書》本，《通志堂經解》本及《學津討原》本等。</p>',9)])])}const m=e(i,[["render",r]]);export{f as __pageData,m as default};
